    """Partenerii din contractele și facturile existente care au CUI intră în registru (fără apel ANAF)."""
    Partener, Contract, Factura = apps.get_model("platforma", "Partener"), apps.get_model("platforma", "Contract"), apps.get_model("platforma", "Factura")
    cache = {}
    def partener(cui, nume):
        cui = re.sub(r"\D", "", cui or "")
        if not cui or not (nume or "").strip():
            return None
        if cui not in cache:
            cache[cui] = Partener.objects.get_or_create(cui=cui, defaults={"denumire": nume.strip()[:200]})[0]
        return cache[cui]
    for c in Contract.objects.all():
        pt = partener(c.cui_partener, c.partener)
        if pt:
            Contract.objects.filter(pk=c.pk).update(firma_partener=pt)
    for f in Factura.objects.all():
        pt = partener(f.cui_furnizor, f.furnizor)
        if pt:
            Factura.objects.filter(pk=f.pk).update(firma_furnizor=pt)


